S = "Hakeem Force Academy"
QS = [
 (S, "With which neighbouring country is Pakistan's friendship described as higher than the mountains and deeper than the oceans?", ["India", "Afghanistan", "China", "Iran"], 2, "Pakistan and China have close strategic, military and economic ties, and this phrase is commonly used for their friendship. CPEC is a major joint project.", "China was among the first countries to recognise Pakistan and established diplomatic relations in 1951.", [1490]),
 (S, "What is the capital of Nepal?", ["Pokhara", "Kathmandu", "Thimphu", "Dhaka"], 1, "Kathmandu is the capital and largest city of Nepal. It lies in the Kathmandu Valley in the Himalayan region.", "Mount Everest, the highest peak in the world, lies on the border of Nepal and China.", [5]),
 (S, "What is the capital of the Netherlands?", ["Rotterdam", "The Hague", "Brussels", "Amsterdam"], 3, "Amsterdam is the constitutional capital of the Netherlands. The government and parliament sit in The Hague.", "The International Court of Justice is located in The Hague.", [88]),
 (S, "Who is the Prime Minister of the Netherlands as of 2026?", ["Mark Rutte", "Dick Schoof", "Rob Jetten", "Geert Wilders"], 2, "Rob Jetten of the D66 party became Prime Minister on 23 February 2026, succeeding Dick Schoof.", "Mark Rutte, who was PM in 2022, later became the Secretary General of NATO in 2024.", [5175, 5187]),
 (S, "Fill in the blank: Mrs. Rehan is not pleased ___ the new servant.", ["upon", "with", "from", "by"], 1, "The adjective pleased is followed by the preposition with when it refers to a person. So the correct sentence is: not pleased with the new servant.", "Other common adjective and preposition pairs are angry with, good at and afraid of.", [1959]),
 (S, "What is a bill called after it has been passed by Parliament and approved by the President of Pakistan?", ["Ordinance", "Act", "Resolution", "Amendment"], 1, "A bill passed by both houses and assented to by the President becomes an Act of Parliament, which is law. An ordinance is a temporary law issued by the President when Parliament is not in session.", "Under Article 75 of the Constitution the President has ten days to assent to a bill or return it.", [2102]),
 (S, "What comes next in the series: 3A, 5C, 7E, ?", ["8F", "9G", "9F", "10G"], 1, "The numbers increase by 2 (3, 5, 7, 9) and the letters skip one letter each time (A, C, E, G). So the next term is 9G.", "The letters A, C, E, G are the 1st, 3rd, 5th and 7th letters of the alphabet.", [3184]),
 (S, "What comes next in the series: 3x+4, 4x+2, ?", ["5x", "5x+1", "5x+2", "6x"], 0, "The coefficient of x increases by 1 each time (3, 4, 5) and the constant decreases by 2 (4, 2, 0). So the next term is 5x+0 = 5x.", "Such a pattern is two arithmetic progressions running together.", [3185]),
 (S, "What comes next in the series: B2, C3, D4, E5, F?", ["G6", "F6", "F5", "G7"], 1, "Each letter moves one step forward and each number increases by 1. F pairs with 6, so the next term is F6.", "B is the 2nd letter, C the 3rd, and so on, so each letter pairs with its own position number.", [3186]),
 (S, "What comes next in the series: 3W, 6X, 9Z, ?", ["12C", "12A", "12B", "15C"], 0, "The numbers increase by 3 (3, 6, 9, 12). The letters move forward by 1, then 2, then 3: W to X to Z to C (after Z the alphabet starts again). So the next term is 12C.", "In such letter series, the alphabet is treated as a circle, so Z is followed by A.", [4463]),
 (S, "Which letter comes next in the series: B, E, J, Q, ?", ["X", "Y", "Z", "W"], 2, "The positions are 2, 5, 10, 17. The gaps are 3, 5, 7, so the next gap is 9 and 17 + 9 = 26, which is Z.", "The positions are one more than the squares 1, 4, 9, 16, and 25 + 1 = 26.", [74]),
 (S, "Which letter comes next in the series: L, M, N, ?", ["P", "O", "Q", "K"], 1, "The letters are in alphabetical order, so O follows N.", "L, M, N, O are the 12th to 15th letters of the alphabet.", [154]),
 (S, "Which letter comes next in the series: O, K, H, F, ?", ["D", "G", "E", "C"], 2, "The positions are 15, 11, 8, 6. The gaps are 4, 3, 2, so the next gap is 1 and 6 - 1 = 5, which is E.", "The gaps decrease by 1 each time.", [1338]),
 (S, "Which number comes next: 1, 4, 9, 16, ?", ["20", "24", "25", "36"], 2, "These are the squares 1x1, 2x2, 3x3, 4x4. The next is 5x5 = 25.", "The gaps between squares are the odd numbers 3, 5, 7, 9.", [4741]),
 (S, "Which number comes next: 155, 65, 165, 75, ?", ["85", "175", "185", "160"], 1, "The terms in odd positions go 155, 165 and the terms in even positions go 65, 75, each rising by 10. So the next term is 165 + 10 = 175.", "This is an alternating series made of two separate series.", [4748]),
 (S, "Which number comes next: 2, 4, 6, 8, ?", ["9", "12", "10", "11"], 2, "Each number is 2 more than the one before it. So 8 + 2 = 10.", "These are the first even natural numbers.", [4751]),
 (S, "Which number comes next: 3, 6, 9, 12, ?", ["14", "16", "18", "15"], 3, "Each number is 3 more than the one before. So 12 + 3 = 15.", "This is the table of 3.", [4752]),
 (S, "Which number comes next: 3, 6, 9, ?", ["10", "11", "12", "13"], 2, "Each number is 3 more than the one before. So 9 + 3 = 12.", "This is the table of 3.", [4753]),
 (S, "Which number comes next: 5, 10, 15, ?", ["25", "20", "18", "30"], 1, "Each number is 5 more than the one before. So 15 + 5 = 20.", "This is the table of 5.", [4754]),
 (S, "Which number comes next: 66, 63, 57, 45, 21, ?", ["-27", "-3", "0", "-21"], 0, "The differences are 3, 6, 12, 24, each double the last. The next difference is 48, so 21 - 48 = -27.", "The same series appears as 66, 63, 57, 45, 21 where the next term after 45 is 21.", [4755]),
 (S, "Sardar Abdur Rab Nishtar served as the Governor of which province of Pakistan?", ["Sindh", "Punjab", "Balochistan", "North-West Frontier Province"], 1, "Sardar Abdur Rab Nishtar, a leader of the Pakistan Movement, was Governor of Punjab from 1949 to 1951.", "Nishtar Medical University in Multan is named after him.", [2981]),
 (S, "In which year was the North-West Frontier Province (NWFP) renamed as Khyber Pakhtunkhwa (KPK)?", ["2008", "2009", "2010", "2012"], 2, "The 18th Amendment, passed in April 2010, renamed NWFP as Khyber Pakhtunkhwa. Some candidates recall 2008, but that is not correct.", "Before the renaming, the province was called NWFP from the British period.", [112, 4294]),
 (S, "In which Hijri year was Zakat made obligatory?", ["1 Hijri", "2 Hijri", "5 Hijri", "9 Hijri"], 1, "According to the commonly taught view, Zakat became obligatory in the second year of Hijri, around the time Ramadan fasting was ordained. Some scholars give slightly different years.", "Sources differ a little on the exact year of Zakat.", [2622]),
 (S, "On which date is the International Day to Combat Islamophobia observed?", ["15 March", "8 March", "22 March", "12 October"], 0, "The UN General Assembly declared 15 March as the International Day to Combat Islamophobia in 2022, on a resolution moved by Pakistan on behalf of the OIC.", "The date marks the anniversary of the 2019 Christchurch mosque attacks.", [2901]),
 (S, "How many nights did the Prophet (PBUH) spend in the Cave of Thawr during the Hijrat?", ["1", "2", "3", "7"], 2, "The Prophet (PBUH) and Hazrat Abu Bakr (RA) hid in the Cave of Thawr for three nights before going on to Madina.", "The Cave of Thawr is near Makkah, on the way to Madina.", [2202, 2203]),
 (S, "How many soldiers did the Quraysh army have at the Battle of Uhud?", ["700", "1000", "3000", "10000"], 2, "The Makkan army led by Abu Sufyan had about 3000 soldiers against around 700 Muslims at the start of the battle (about 1000 left with Abdullah bin Ubayy).", "The Quraysh army had 200 horsemen and Khalid bin Walid led their cavalry.", [2208]),
 (S, "Which type of noun is Islamabad?", ["Common noun", "Proper noun", "Collective noun", "Abstract noun"], 1, "A proper noun is the name of a particular person, place or thing. Islamabad is the name of one specific city, so it is a proper noun and it is written with a capital letter.", "A common noun such as city names any one of a class.", [2784, 4086]),
 (S, "School is a noun. Which pronoun can be used in its place?", ["he", "she", "it", "they"], 2, "A school is a singular, non-living thing, so the pronoun it is used for it.", "The plural pronoun for schools is they.", [2982]),
 (S, "What is the word used in place of a noun called?", ["Adjective", "Pronoun", "Adverb", "Verb"], 1, "A pronoun is used in place of a noun to avoid repeating it, such as he, she, it and they.", "Words like he, she and it are personal pronouns.", [3900]),
 (S, "A person walks 7 miles towards the north, then turns left, then turns left again. In which direction is he going now?", ["East", "West", "South", "North"], 2, "Facing north, a left turn makes him face west. Turning left again from west makes him face south.", "Two successive left turns make a total turn of 180 degrees.", [486]),
 (S, "What is the total number of nuclear-armed countries in the world today?", ["5", "7", "9", "12"], 2, "Nine countries have nuclear weapons: the USA, Russia, the UK, France, China, India, Pakistan, Israel (undeclared) and North Korea.", "Pakistan is the only Muslim country with nuclear weapons.", [4018]),
 (S, "What was the code name of Pakistan's first nuclear tests of 28 May 1998?", ["Chagai-I", "Shaheen-I", "Ghauri-I", "Babur-I"], 0, "Pakistan carried out five nuclear tests in the Chagai Hills on 28 May 1998 under the name Chagai-I. A sixth test followed on 30 May 1998 as Chagai-II.", "Shaheen, Ghauri and Babur are names of Pakistani missiles.", [4148]),
 (S, "On which date did Pakistan become a nuclear power by conducting nuclear tests?", ["11 May 1998", "28 May 1998", "30 May 1998", "14 August 1998"], 1, "Pakistan carried out its tests in the Chagai Hills on 28 May 1998, responding to India's tests of 11 and 13 May 1998.", "Pakistan celebrates 28 May as Youm-e-Takbeer.", [4221]),
 (S, "According to the commonly accepted belief, how many Prophets (Anbiya) were sent by Allah?", ["14000", "24000", "124000", "313"], 2, "A well-known narration gives the number of Prophets as 124,000. The exact number is known only to Allah.", "The Quran names 25 Prophets. Sources differ about the number of Rasools, commonly given as 313.", [3850]),
 (S, "13, 15, 17 and 19 are what type of numbers?", ["Even numbers", "Odd numbers", "Perfect squares", "Perfect numbers"], 1, "Each of these numbers leaves a remainder of 1 when divided by 2, so they are odd numbers.", "The only even prime number is 2.", [1599]),
 (S, "If a set has two elements, how many elements are in its power set?", ["2", "3", "4", "8"], 2, "The power set of a set with n elements has 2 to the power n elements. For n = 2 this is 4: the empty set, two single-element subsets, and the set itself.", "A set with 3 elements has a power set of 8 elements.", [2438]),
]
